template:
% 参数由系统自动注入：\def\radiusa{3} \def\radiusb{2} \def\dist{2.5} \def\showcenters{1} \def\showline{1} \def\showring{0}
% 视觉归一化：把两圆最宽跨度缩放到 6（单位由 coordScale 决定）。
\pgfmathsetmacro{\figscale}{6 / (\dist + \radiusa + \radiusb)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (O1) at (0,0);
  \coordinate (O2) at (\dist,0);
  % 两圆之间区域 / 同心圆环（even-odd 填充）
  \ifnum\showring>0
    \fill[green!12, even odd rule] (O1) circle [radius=\radiusa] (O2) circle [radius=\radiusb];
  \fi
  \draw[thick] (O1) circle [radius=\radiusa];
  \draw[thick] (O2) circle [radius=\radiusb];
  % 连心线 O1O2
  \ifnum\showline>0
    \draw[thick] (O1) -- (O2);
  \fi
  % 圆心
  \ifnum\showcenters>0
    \fill (O1) circle [radius=1.6pt];
    \fill (O2) circle [radius=1.6pt];
    \node[below=3pt] at (O1) {$O_1$};
    \node[below=3pt] at (O2) {$O_2$};
  \fi
\end{tikzpicture}
